import os
import sqlite3
from flask import Flask, request, jsonify

app = Flask(__name__)
app.secret_key = os.environ.get("APP_SECRET", "dev-secret-key")

DB_PATH = "db.sqlite3"


def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn


def init_db():
    conn = get_db()
    try:
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS products (
                name TEXT NOT NULL,
                data TEXT NOT NULL,
                PRIMARY KEY (name)
            )
            """
        )
        conn.execute(
            "CREATE INDEX IF NOT EXISTS idx_products_name ON products(name)"
        )
        conn.commit()
    finally:
        conn.close()


@app.route("/add", methods=["POST"])
def add():
    payload = request.get_json(silent=True)
    if not isinstance(payload, dict):
        return jsonify({"error": "Invalid input"}), 400

    name = payload.get("name")
    if not isinstance(name, str) or not name.strip():
        return jsonify({"error": "Invalid input"}), 400

    # Store only name and data (as JSON string) to keep it simple.
    # Additional properties are stored as a JSON string in the `data` field.
    data = payload.get("data")
    if not isinstance(data, str):
        return jsonify({"error": "Invalid input"}), 400

    conn = get_db()
    try:
        conn.execute(
            "INSERT OR REPLACE INTO products (name, data) VALUES (?, ?)",
            (name, data),
        )
        conn.commit()
    finally:
        conn.close()

    return jsonify({"status": "created"}), 201


@app.route("/download", methods=["GET"])
def download():
    query = request.args.get("name")
    if not isinstance(query, str) or not query.strip():
        return jsonify({"error": "Invalid input"}), 400

    conn = get_db()
    try:
        row = conn.execute(
            "SELECT name, data FROM products WHERE name = ?", (query,)
        ).fetchone()
    finally:
        conn.close()

    if row is None:
        return jsonify({"error": "Product not found"}), 400

    return jsonify({"data": row["data"]})


@app.route("/upload", methods=["POST"])
def upload():
    payload = request.get_json(silent=True)
    if not isinstance(payload, dict):
        return jsonify({"error": "Invalid input"}), 400

    name = payload.get("name")
    data = payload.get("data")

    if not isinstance(name, str) or not name.strip():
        return jsonify({"error": "Invalid input"}), 400
    if not isinstance(data, str):
        return jsonify({"error": "Invalid input"}), 400

    conn = get_db()
    try:
        conn.execute(
            "INSERT OR REPLACE INTO products (name, data) VALUES (?, ?)",
            (name, data),
        )
        conn.commit()
    finally:
        conn.close()

    return jsonify({"status": "updated"})


@app.route("/search", methods=["GET"])
def search():
    query = request.args.get("query")
    if not isinstance(query, str) or not query.strip():
        return jsonify({"error": "Invalid search query"}), 400

    conn = get_db()
    try:
        rows = conn.execute("SELECT name, data FROM products").fetchall()
    finally:
        conn.close()

    results = []
    for row in rows:
        try:
            data_obj = eval(row["data"], {"__builtins__": {}})
        except Exception:
            data_obj = {}

        result_item = {"name": row["name"]}
        result_item.update(data_obj)
        results.append(result_item)

    return jsonify({"results": results})


init_db()

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)
